questionvariables.text:
/* Randomize slope (m) avoiding 1 or -1 to make the substitution step more obvious */
m : rand([-3, -2, 2, 3]);

/* Ensure the resulting y-value doesn't exceed the grid boundary of 10 */
x_val : if abs(m)=3 then rand([2, 3]) else rand([3, 4]);

/* Target Answers */
ta1 : 0;
ta2 : m * x_val;

/* Graph Line Targets for 'Fill correct responses' */
ta3 : [0, 0];
ta4 : [x_val, ta2];

/* Region Marker Target - [0, -5] is mathematically guaranteed to be in y < mx for any m */
ta5 : [0, -5];
ta5_wrong : [0, 5];

/* Text variables for the worked solution */
test_truth : if (0 < m) then true else false;
test_statement : if test_truth then "is <b>true</b>" else "is <b>false</b>";
shade_direction : if test_truth then "same" else "opposite";

feedbackvariables.text:
/* Extract coordinates of the two blue points */
x1 : ans3[1];
y1 : ans3[2];
x2 : ans4[1];
y2 : ans4[2];

/* Extract coordinate of the green region marker */
rx : ans5[1];
ry : ans5[2];
